// Offline cache for Rising DB. Generated by tools/build_web.py; edits are overwritten.
const CORE_CACHE = "risingdb-core-29e037d9180b";
const IMG_CACHE = "risingdb-img-5f269967884f";
const CORE = [
"./",
"app.js",
"apple-touch-icon.png",
"icon-192.png",
"icon-512.png",
"icon-maskable.png",
"index.html",
"manifest.webmanifest",
"style.css",
"tools.js",
"data/activities.js",
"data/artifacts.js",
"data/characters.js",
"data/crafting.js",
"data/draws.js",
"data/duels.js",
"data/emanare.js",
"data/enemies.js",
"data/events.js",
"data/explore.js",
"data/farm.js",
"data/fish.js",
"data/guides.js",
"data/icons.js",
"data/index.js",
"data/items.js",
"data/loot.js",
"data/lore.js",
"data/modes.js",
"data/modifiers.js",
"data/new.js",
"data/perks.js",
"data/reference.js",
"data/relic_enhancement.js",
"data/resonance.js",
"data/sets.js",
"data/shops.js",
"data/tracks.js",
"data/triumphs.js",
"data/weapon_mods.js",
"data/weapons.js"
];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(CORE_CACHE).then((c) => c.addAll(CORE)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(caches.keys().then((keys) => Promise.all(
    keys.filter((k) => k.startsWith("risingdb-") && k !== CORE_CACHE && k !== IMG_CACHE).map((k) => caches.delete(k))
  )).then(() => self.clients.claim()));
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  const url = new URL(req.url);
  if (req.method !== "GET" || url.origin !== location.origin) return;
  const isImg = url.pathname.includes("/img/");
  event.respondWith(
    // ignoreSearch: index.html?q=term is the same page
    caches.match(req, { ignoreSearch: req.mode === "navigate" }).then((hit) => hit || fetch(req).then((res) => {
      if (res.ok) {
        const copy = res.clone();
        caches.open(isImg ? IMG_CACHE : CORE_CACHE).then((c) => c.put(req, copy));
      }
      return res;
    }))
  );
});
